// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am, uint256 minSum) public {
        // Set a MinSum value; the call to SetMinSum can only be done once and before initialized
        vm.assume(minSum > 0 && minSum < type(uint256).max);
        c.SetMinSum(minSum);
        c.Initialized();

        // Record MinSum before the Collect call
        uint256 minSumBefore = c.MinSum();

        // Call Collect with a given amount (may revert if balance insufficient, etc.)
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));
        // Suppress unused variable warning:
        success;

        // Assert that MinSum remained unchanged
        assertTrue(c.MinSum() == minSumBefore, "MinSum changed after Collect");
    }
}

